package fr.wokgui.studiophotopicker;
import android.app.Activity;import android.os.Bundle;import android.content.Intent;import android.content.ClipData;import android.net.Uri;import android.widget.*;import java.io.File;import java.util.*;
public class PickerActivity extends Activity {
 public void onCreate(Bundle state){super.onCreate(state);LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);layout.setPadding(32,24,32,24);TextView title=new TextView(this);title.setText("Photos de test Studio — choisissez les photos puis Ouvrir");title.setTextSize(22);layout.addView(title);ScrollView scroll=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);layout.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));final ArrayList<CheckBox> boxes=new ArrayList<CheckBox>();File[] files=new File("/sdcard/Pictures/InterfaceStudio").listFiles();if(files!=null){Arrays.sort(files);for(File file:files){if(!file.isFile()||!file.getName().matches("[a-zA-Z0-9_.-]+\\.(?i:png|jpg|jpeg|webp)"))continue;CheckBox box=new CheckBox(this);box.setText(file.getName());box.setTextSize(20);list.addView(box);boxes.add(box);}}Button open=new Button(this);open.setText("Ouvrir les photos sélectionnées");layout.addView(open);open.setOnClickListener(v->{ArrayList<Uri> selected=new ArrayList<Uri>();for(CheckBox box:boxes)if(box.isChecked())selected.add(Uri.parse("content://fr.wokgui.studiophotopicker.photos/"+box.getText()));if(selected.isEmpty()){Toast.makeText(this,"Choisissez au moins une photo",Toast.LENGTH_SHORT).show();return;}Intent result=new Intent();result.setData(selected.get(0));ClipData clips=new ClipData("Photos Studio",new String[]{"image/*"},new ClipData.Item(selected.get(0)));if(getIntent().getBooleanExtra(Intent.EXTRA_ALLOW_MULTIPLE,false))for(int i=1;i<selected.size();i++)clips.addItem(new ClipData.Item(selected.get(i)));result.setClipData(clips);result.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);setResult(RESULT_OK,result);finish();});setContentView(layout);if(!boxes.isEmpty())boxes.get(0).requestFocus();}
}
